{"content": "import { FormEvent, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import "./style.css";

type Recipe = { id: string; name: string; category: string; image: string; ingredients: string[]; steps: string[]; createdAt: string };
const seed: Recipe[] = [
  { id: "seed-1", name: "番茄鸡蛋面", category: "家常菜", image: "https://images.unsplash.com/photo-1621996346565-e3dbc646d9a9?auto=format&fit=crop&w=900&q=80", ingredients: ["鸡蛋 2 个", "番茄 2 个", "挂面 1 把", "葱花、盐、香油适量"], steps: ["番茄切块，鸡蛋打散。", "热锅炒蛋盛出，再炒番茄至出汁。", "加水煮开，放入面条和鸡蛋，调味出锅。"], createdAt: "2024-01-01" },
  { id: "seed-2", name: "周末柠檬磅蛋糕", category: "烘焙", image: "https://images.unsplash.com/photo-1519915028121-7d3463d20b13?auto=format&fit=crop&w=900&q=80", ingredients: ["黄油 120g", "低筋面粉 150g", "鸡蛋 2 个", "柠檬 1 个", "细砂糖 100g"], steps: ["黄油软化后与糖打发。", "分次加入蛋液，筛入面粉拌匀。", "加入柠檬皮屑，170°C 烘烤 45 分钟。"], createdAt: "2024-01-02" },
  { id: "seed-3", name: "桂花蜜茶", category: "饮品", image: "https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=80", ingredients: ["红茶 1 包", "桂花蜜 2 勺", "热水 300ml", "柠檬片 2 片"], steps: ["热水冲泡红茶 3 分钟。", "加入桂花蜜搅匀，放入柠檬片即可。"], createdAt: "2024-01-03" },
];
const defaults = ["家常菜", "早餐", "汤羹", "烘焙", "饮品"];
const read = <T,>(key: string, fallback: T): T => { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback; } catch { return fallback; } };
const lines = (value: string) => value.split("\n").map((item) => item.trim()).filter(Boolean);

function App() {
  const [recipes, setRecipes] = useState<Recipe[]>(() => read("kitchen-recipes", seed));
  const [customCategories, setCustomCategories] = useState<string[]>(() => read("kitchen-categories", []));
  const [activeCategory, setActiveCategory] = useState("全部");
  const [query, setQuery] = useState("");
  const [ingredientQuery, setIngredientQuery] = useState("");
  const [modal, setModal] = useState<"form" | "detail" | null>(null);
  const [editing, setEditing] = useState<Recipe | null>(null);
  const [selected, setSelected] = useState<Recipe | null>(null);
  useEffect(() => { localStorage.setItem("kitchen-recipes", JSON.stringify(recipes)); }, [recipes]);
  useEffect(() => { localStorage.setItem("kitchen-categories", JSON.stringify(customCategories)); }, [customCategories]);
  const categories = [...defaults, ...customCategories.filter((item) => !defaults.includes(item))];
  const visible = useMemo(() => { const nameTerm = query.trim().toLowerCase(); const ingredientTerm = ingredientQuery.trim().toLowerCase(); return recipes.filter((recipe) => (activeCategory === "全部" || recipe.category === activeCategory) && (!nameTerm || recipe.name.toLowerCase().includes(nameTerm)) && (!ingredientTerm || recipe.ingredients.some((ingredient) => ingredient.toLowerCase().includes(ingredientTerm)))); }, [recipes, activeCategory, query, ingredientQuery]);
  const openNew = () => { setEditing(null); setModal("form"); };
  const openEdit = (recipe: Recipe) => { setEditing(recipe); setModal("form"); setSelected(null); };
  const remove = (recipe: Recipe) => { if (window.confirm(`确定要删除「${recipe.name}」吗？`)) { setRecipes((items) => items.filter((item) => item.id !== recipe.id)); setSelected(null); setModal(null); } };
  const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const category = String(form.get("category") || "家常菜"); const recipe: Recipe = { id: editing?.id || crypto.randomUUID(), name: String(form.get("name") || "未命名菜谱"), category, image: String(form.get("image") || ""), ingredients: lines(String(form.get("ingredients") || "")), steps: lines(String(form.get("steps") || "")), createdAt: editing?.createdAt || new Date().toISOString() }; setRecipes((items) => editing ? items.map((item) => item.id === editing.id ? recipe : item) : [recipe, ...items]); setModal(null); setEditing(null); };
  const addCategory = () => { const value = window.prompt("输入新分类名称"); if (value?.trim() && !categories.includes(value.trim())) { setCustomCategories((items) => [...items, value.trim()]); setActiveCategory(value.trim()); } };
  return <div className="app-shell">
    <header className="topbar"><div className="brand"><span className="brand-mark">✦</span><div><strong>灶台边</strong><span>家庭菜谱簿</span></div></div><button className="primary add-top" onClick={openNew}><span>＋</span> 写下新菜谱</button></header>
    <main className="content"><section className="intro"><div><p className="eyebrow">MY KITCHEN NOTEBOOK <span>·</span> {new Date().getFullYear()}</p><h1>把喜欢的味道，<em>留在手边。</em></h1><p className="subcopy">一页一页，记下家里常做的菜，也记下每一次分享的心意。</p></div><div className="stats"><b>{recipes.length}</b><span>道私房菜</span></div></section>
      <section className="toolbar"><div className="categories"><button className={activeCategory === "全部" ? "active" : ""} onClick={() => setActiveCategory("全部")}>全部 <small>{recipes.length}</small></button>{categories.map((category) => <button key={category} className={activeCategory === category ? "active" : ""} onClick={() => setActiveCategory(category)}>{category}</button>)}<button className="add-category" onClick={addCategory} title="新增分类">＋ 新分类</button></div><div className="search-group"><label className="search"><span>⌕</span><input aria-label="搜索菜谱名称" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="搜索菜谱..." /></label><label className="search"><span>⌁</span><input aria-label="按食材搜索" value={ingredientQuery} onChange={(event) => setIngredientQuery(event.target.value)} placeholder="按食材搜索..." /></label></div></section>
      <div className="list-heading"><h2>{activeCategory === "全部" ? "最近收藏" : activeCategory}</h2><span>{visible.length} 道菜</span></div>
      {visible.length ? <section className="recipe-grid">{visible.map((recipe, index) => <article className={`recipe-card card-${index % 3}`} key={recipe.id} onClick={() => { setSelected(recipe); setModal("detail"); }}><div className="image-wrap">{recipe.image ? <img src={recipe.image} alt="" onError={(event) => { event.currentTarget.style.display = "none"; event.currentTarget.parentElement?.classList.add("image-fallback"); }} /> : <div className="image-fallback">✦</div>}<span className="tag">{recipe.category}</span><button className="more" aria-label="查看详情" onClick={(event) => { event.stopPropagation(); setSelected(recipe); setModal("detail"); }}>···</button></div><div className="card-body"><h3>{recipe.name}</h3><p>{recipe.ingredients.slice(0, 3).join(" · ")}{recipe.ingredients.length > 3 ? " · ..." : ""}</p><div className="card-foot"><span>食材 {recipe.ingredients.length} 样</span><span>→</span></div></div></article>)}</section> : <div className="empty"><span>✦</span><h3>还没有找到这道菜</h3><p>换个关键词，或写下一道新菜谱吧。</p><button className="primary" onClick={openNew}>＋ 写下新菜谱</button></div>}
    </main>
    {modal === "form" && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setModal(null)}><form className="modal form-modal" onSubmit={save}><div className="modal-head"><div><p className="eyebrow">{editing ? "EDIT RECIPE" : "NEW RECIPE"}</p><h2>{editing ? "修改这道菜" : "写下新菜谱"}</h2></div><button type="button" className="close" onClick={() => setModal(null)}>×</button></div><label>菜谱名称<input name="name" required defaultValue={editing?.name} placeholder="比如：妈妈的红烧肉" /></label><div className="form-row"><label>分类<select name="category" defaultValue={editing?.category || "家常菜"}>{categories.map((category) => <option key={category}>{category}</option>)}</select></label><label>图片链接<input name="image" type="url" defaultValue={editing?.image} placeholder="https://..." /></label></div><label>食材 <span className="hint">每行一种</span><textarea name="ingredients" required defaultValue={editing?.ingredients.join("\n")} placeholder={'五花肉 500g\n冰糖 30g\n生抽 2 勺'} /></label><label>步骤 <span className="hint">每行一步</span><textarea name="steps" required defaultValue={editing?.steps.join("\n")} placeholder={'切好食材，准备调料。\n热锅下油，慢慢煸炒。'} /></label><div className="form-actions"><button type="button" className="ghost" onClick={() => setModal(null)}>取消</button><button className="primary" type="submit">保存菜谱</button></div></form></div>}
