    </main>
    {modal === "form" && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setModal(null)}><form className="modal form-modal" onSubmit={save}><div className="modal-head"><div><p className="eyebrow">{editing ? "EDIT RECIPE" : "NEW RECIPE"}</p><h2>{editing ? "修改这道菜" : "写下新菜谱"}</h2></div><button type="button" className="close" onClick={() => setModal(null)}>×</button></div><label>菜谱名称<input name="name" required defaultValue={editing?.name} placeholder="比如：妈妈的红烧肉" /></label><div className="form-row"><label>分类<select name="category" defaultValue={editing?.category || "家常菜"}>{categories.map((category) => <option key={category}>{category}</option>)}</select></label><label>图片链接<input name="image" type="url" defaultValue={editing?.image} placeholder="https://..." /></label></div><label>食材 <span className="hint">每行一种</span><textarea name="ingredients" required defaultValue={editing?.ingredients.join("\n")} placeholder={'五花肉 500g\n冰糖 30g\n生抽 2 勺'} /></label><label>步骤 <span className="hint">每行一步</span><textarea name="steps" required defaultValue={editing?.steps.join("\n")} placeholder={'切好食材，准备调料。\n热锅下油，慢慢煸炒。'} /></label><div className="form-actions"><button type="button" className="ghost" onClick={() => setModal(null)}>取消</button><button className="primary" type="submit">保存菜谱</button></div></form></div>}
    {modal === "detail" && selected && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setModal(null)}><article className="modal detail-modal"><div className="detail-image">{selected.image ? <img src={selected.image} alt={selected.name} onError={(event) => { event.currentTarget.style.display = "none"; event.currentTarget.parentElement?.classList.add("image-fallback"); }} /> : <div className="image-fallback">✦</div>}</div><div className="detail-content"><div className="modal-head"><div><span className="tag static">{selected.category}</span><h2>{selected.name}</h2></div><button className="close" onClick={() => setModal(null)}>×</button></div><div className="detail-columns"><div><h4>食材清单</h4><ul>{selected.ingredients.map((item) => <li key={item}>{item}</li>)}</ul></div><div><h4>做法</h4><ol>{selected.steps.map((item) => <li key={item}>{item}</li>)}</ol></div></div><div className="form-actions"><button className="danger ghost" onClick={() => remove(selected)}>删除</button><button className="primary" onClick={() => openEdit(selected)}>编辑菜谱</button></div></div></article></div>}
  </div>;
}
createRoot(document.getElementById("root")!).render(<App />);
