{"content": "@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Playfair+Display:wght@600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');
:root{font-family:'Plus Jakarta Sans',sans-serif;color:#302d29;background:#f7f4ee;font-synthesis:none;--ink:#302d29;--muted:#817d74;--rust:#c85d3c;--sage:#667b5c;--paper:#fffdf9;--line:#e5dfd5}*{box-sizing:border-box}body{margin:0;min-width:320px;background:radial-gradient(circle at 90% 0,#fff8e7 0,transparent 25%),#f7f4ee}.app-shell{min-height:100vh}.topbar{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 clamp(20px,5vw,76px);background:rgba(255,253,249,.72);backdrop-filter:blur(12px)}.brand{display:flex;align-items:center;gap:12px}.brand-mark{display:grid;place-items:center;background:var(--rust);color:#fff;width:34px;height:34px;border-radius:50%;font-size:18px}.brand strong{display:block;font-family:'Playfair Display',serif;font-size:20px;line-height:1}.brand div span{display:block;color:var(--muted);font-size:10px;letter-spacing:2px;margin-top:5px}.primary{border:0;background:var(--rust);color:white;border-radius:5px;padding:12px 18px;font-weight:700;cursor:pointer;box-shadow:0 4px 12px #c85d3c24}.primary:hover{background:#ad492d}.add-top{font-size:13px}.add-top span{font-size:18px;vertical-align:-1px;margin-right:4px}.content{max-width:1240px;margin:0 auto;padding:60px clamp(20px,5vw,76px) 80px}.intro{display:flex;justify-content:space-between;align-items:end;padding-bottom:52px}.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:1.8px;color:var(--sage);margin:0 0 15px}.eyebrow span{color:#c3b99d}.intro h1{font:700 clamp(35px,5vw,64px)/1.08 'Playfair Display',serif;letter-spacing:-1px;margin:0;color:var(--ink)}.intro h1 em{font-style:normal;color:var(--rust)}.subcopy{color:var(--muted);font-size:14px;margin:18px 0 0;max-width:480px;line-height:1.7}.stats{border-left:1px solid var(--line);padding-left:25px;display:grid;gap:4px;min-width:108px}.stats b{font:700 42px 'Playfair Display',serif;color:var(--rust)}.stats span{font-size:11px;color:var(--muted)}.toolbar{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:17px 0;display:flex;justify-content:space-between;gap:20px;align-items:center}.categories{display:flex;gap:4px;align-items:center;overflow:auto;scrollbar-width:none}.categories button{border:0;background:transparent;padding:9px 12px;color:var(--muted);font:500 12px 'Plus Jakarta Sans';white-space:nowrap;cursor:pointer;border-radius:4px}.categories button:hover,.categories button.active{color:var(--ink);background:#eee8db}.categories button.active{font-weight:700}.categories small{color:var(--rust);font-size:10px}.categories .add-category{color:var(--sage)}.search-group{display:flex;gap:18px;flex:none}.search{display:flex;align-items:center;border-bottom:1px solid #cfc7b9;padding:7px 0;width:170px}.search span{font-size:22px;color:var(--muted);transform:rotate(-20deg);margin-right:6px}.search input{border:0;background:transparent;outline:0;width:100%;font:12px 'Plus Jakarta Sans';color:var(--ink)}.list-heading{display:flex;align-items:baseline;justify-content:space-between;margin:36px 0 18px}.list-heading h2{font:700 24px 'Playfair Display',serif;margin:0}.list-heading span{font:11px 'DM Mono';color:var(--muted)}.recipe-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.recipe-card{background:var(--paper);border:1px solid var(--line);cursor:pointer;transition:transform .2s,box-shadow .2s}.recipe-card:hover{transform:translateY(-4px);box-shadow:0 12px 28px #4c3a2514}.image-wrap{height:210px;background:#e9e4da;position:relative;overflow:hidden}.image-wrap img,.detail-image img{width:100%;height:100%;object-fit:cover;display:block}.image-wrap:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,#2f261000 55%,#2f261c38)}.tag{position:absolute;z-index:1;left:14px;top:14px;background:#fffdf9e8;color:var(--sage);padding:6px 9px;font:500 10px 'DM Mono';border-radius:2px}.more{position:absolute;z-index:2;right:11px;top:10px;border:0;background:#fffdf9db;color:var(--ink);width:31px;height:27px;cursor:pointer;letter-spacing:2px}.image-fallback{height:100%;display:grid;place-items:center;color:var(--rust);font-size:35px;background:repeating-linear-gradient(45deg,#eee6d9,#eee6d9 8px,#f6f0e7 8px,#f6f0e7 16px)}.card-body{padding:18px 18px 15px}.card-body h3{font:700 20px 'Playfair Display',serif;margin:0 0 9px}.card-body p{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin:0}.card-foot{border-top:1px solid var(--line);margin-top:18px;padding-top:12px;display:flex;justify-content:space-between;color:var(--muted);font:10px 'DM Mono'}.card-foot span:last-child{color:var(--rust);font-size:18px;line-height:10px}.empty{text-align:center;padding:80px 20px;border:1px dashed #d6cdbd}.empty>span{color:var(--rust);font-size:30px}.empty h3{font:700 22px 'Playfair Display';margin:12px 0 4px}.empty p{color:var(--muted);font-size:13px;margin-bottom:22px}.modal-backdrop{position:fixed;inset:0;background:#2e271f66;z-index:5;display:grid;place-items:center;padding:20px}.modal{background:var(--paper);width:min(650px,100%);max-height:92vh;overflow:auto;box-shadow:0 18px 60px #241a1280}.form-modal{padding:30px}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px}.modal-head h2{font:700 30px 'Playfair Display';margin:0}.close{border:0;background:transparent;font-size:28px;color:var(--muted);cursor:pointer;line-height:1}.form-modal label{display:block;font-size:12px;font-weight:700;margin:16px 0;color:var(--ink)}.form-modal input,.form-modal textarea,.form-modal select{display:block;width:100%;margin-top:7px;border:1px solid #dcd4c6;background:#fffefa;padding:12px;font:13px 'Plus Jakarta Sans';color:var(--ink);outline-color:var(--rust);border-radius:3px}.form-modal textarea{min-height:95px;resize:vertical;line-height:1.7}.form-row{display:grid;grid-template-columns:1fr 1.5fr;gap:16px}.hint{float:right;color:var(--muted);font-weight:400;font-size:10px}.form-actions{display:flex;justify-c